pub fn apply_inference_params(
    body: &mut serde_json::Value,
    temperature: Option<f64>,
    top_p: Option<f64>,
) {
    if let Some(t) = temperature {
        // Anthropic 限制 [0, 1]，OpenAI 允许到 2.0；条目覆盖来自 ModelEntry.temperature，
        // schema::effective_inference 未做范围钳制——这里在写入前断言合法区间，
        // 否则上游 provider 会以 400 拒掉整轮请求、审计日志与用户报错口径不一致。
        debug_assert!((0.0..=2.0).contains(&t), "temperature {t} 超出合法区间");
        body["temperature"] = serde_json::json!(t);
    }
    if let Some(p) = top_p {
        debug_assert!((0.0..=1.0).contains(&p), "top_p {p} 超出合法区间");
        body["top_p"] = serde_json::json!(p);
    }
}

